SELECT id, name, category, description, image, points_required AS pointsRequired, stock, total_stock AS totalStock, exchange_limit AS exchangeLimit, status, sort_order AS sortOrder, create_time AS createTime, update_time AS updateTime FROM product
AND status = #{query.status}
AND category = #{query.category}
AND points_required >= #{query.minPoints}
AND points_required <= #{query.maxPoints}
AND (name LIKE CONCAT('%', #{query.keyword}, '%') OR description LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY sort_order ASC, create_time DESC LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM product


        AND status = #{query.status}


        AND category = #{query.category}


        AND points_required >= #{query.minPoints}


        AND points_required <= #{query.maxPoints}


        AND (name LIKE CONCAT('%', #{query.keyword}, '%') OR description LIKE CONCAT('%', #{query.keyword}, '%'))
